    #[test]
    fn sankey_layout_extreme_and_invalid_values_keep_geometry_finite() {
        for source in [
            "sankey-beta\nA,M,1e308\nB,M,1e308\nC,M,1e308\nM,Z,1e308\n",
            "sankey-beta\nA,M,NaN\nB,M,inf\nC,M,-2\nD,M,0\nM,Z,not-a-number\n",
        ] {
            let ir = parse(source).ir;
            let layout = layout_diagram_sankey(&ir);
            assert!(!layout.nodes.is_empty());
            for bounds in
                std::iter::once(layout.bounds).chain(layout.nodes.iter().map(|node| node.bounds))
            {
                assert!(
                    bounds.x.is_finite()
                        && bounds.y.is_finite()
                        && bounds.width.is_finite()
                        && bounds.height.is_finite(),
                    "flow magnitudes produced invalid geometry: {bounds:?}"
                );
            }
            for (index, node) in layout.nodes.iter().enumerate() {
                for other in &layout.nodes[index + 1..] {
                    assert!(
                        !rects_overlap(node.bounds, other.bounds),
                        "normalized Sankey nodes overlap: {node:?}, {other:?}"
                    );
                }
            }
            for edge in &layout.edges {
                assert!(
                    edge.points
                        .iter()
                        .all(|point| point.x.is_finite() && point.y.is_finite()),
                    "invalid node geometry reached an edge: {edge:?}"
                );
            }
        }
    }

    /// Build a `packet-beta` IR from `(id, start_bit, end_bit)` triples.
    fn packet_ir(fields: &[(&str, u32, u32)]) -> MermaidDiagramIr {
        let mut ir = MermaidDiagramIr::empty(DiagramType::PacketBeta);
        let mut meta = fm_core::IrPacketMeta::default();
        for (index, (id, start, end)) in fields.iter().enumerate() {
            ir.nodes.push(IrNode {
                id: (*id).to_string(),
                ..IrNode::default()
            });
            meta.fields.push(fm_core::IrPacketField {
                node: IrNodeId(index),
                start_bit: *start,
                end_bit: *end,
            });
        }
        ir.packet_meta = Some(meta);
        ir
    }

    /// Width is `bits * bit_width` and x is the start bit's offset in its row — nothing else
    /// (bd-51tz). Two 16-bit fields must be identical in width even though their ids differ in
    /// length, and the 32-bit field must be exactly twice as wide, not merely wider.
    #[test]
    fn packet_layout_derives_width_and_x_from_the_bit_range() {
        let ir = packet_ir(&[
            ("a", 0, 15),
            ("a_much_longer_id_than_the_others", 16, 31),
            ("c", 32, 63),
        ]);
        let layout = layout_diagram_traced_with_algorithm(&ir, LayoutAlgorithm::Packet).layout;
        let boxes: BTreeMap<&str, LayoutRect> = layout
            .nodes
            .iter()
            .map(|n| (n.node_id.as_str(), n.bounds))
            .collect();

        let a = boxes["a"];
        let b = boxes["a_much_longer_id_than_the_others"];
        let c = boxes["c"];
        assert!(
            (a.width - b.width).abs() < 0.001,
            "two 16-bit fields must be equally wide, got {} and {}",
            a.width,
            b.width
        );
        assert!(
            (c.width - a.width * 2.0).abs() < 0.001,
            "a 32-bit field must be exactly twice a 16-bit one, got {} vs {}",
            c.width,
            a.width
        );
        assert!(
            (b.x - (a.x + a.width)).abs() < 0.001,
            "bit 16 must start where bit 15 ends: {} vs {}",
            b.x,
            a.x + a.width
        );
        assert!(
            (a.y - b.y).abs() < 0.001 && c.y > a.y,
            "bits 0-31 share a row and bits 32-63 wrap to the next: {} {} {}",
            a.y,
            b.y,
            c.y
        );
        assert!(
            layout.edges.is_empty(),
            "a bit ruler draws no connectors between fields"
        );
    }

    /// Rows wrap every 32 bits, so bit 32 returns to the left edge under bit 0.
    #[test]
    fn packet_layout_wraps_rows_every_32_bits() {
        let ir = packet_ir(&[("r0", 0, 31), ("r1", 32, 63), ("r2", 64, 95)]);
        let layout = layout_diagram_traced_with_algorithm(&ir, LayoutAlgorithm::Packet).layout;
        let rows: Vec<LayoutRect> = layout.nodes.iter().map(|n| n.bounds).collect();
        assert!(
            rows.windows(2).all(|w| (w[0].x - w[1].x).abs() < 0.001),
            "every full row starts at the same x: {rows:?}"
        );
        assert!(
            rows.windows(2).all(|w| w[1].y > w[0].y),
            "each 32-bit row sits below the previous: {rows:?}"
        );
        let pitch = rows[1].y - rows[0].y;
        assert!(
            ((rows[2].y - rows[1].y) - pitch).abs() < 0.001,
            "row pitch must be uniform: {rows:?}"
        );
    }

    /// A field crossing a 32-bit row boundary is CUT at it, and the remainder carried to the next
    /// row — the split mermaid-js 11.15.0's `getNextFittingBlock` performs (bd-8vr0). This replaces
    /// the test that pinned the previous one-overflowing-box divergence.
    ///
    /// All four of bd-8vr0's acceptance criteria are asserted here.
    #[test]
    fn packet_layout_splits_a_row_straddling_field_across_its_rows() {
        let ir = packet_ir(&[("aligned", 0, 15), ("straddles", 16, 47)]);
        let traced = layout_diagram_traced_with_algorithm(&ir, LayoutAlgorithm::Packet);
        let layout = traced.layout;
        let boxes: BTreeMap<&str, LayoutRect> = layout
            .nodes
            .iter()
            .map(|n| (n.node_id.as_str(), n.bounds))
            .collect();
        let aligned = boxes["aligned"];
        let head = boxes["straddles"];
        let continuations = &layout.extensions.packet_field_continuations;

        // (1) Two boxes: the head on row 0 and one continuation on row 1.
        assert_eq!(
            continuations.len(),
            1,
            "bits 16-47 cross one row boundary, so it needs exactly one continuation: \
             {continuations:?}"
        );
        let tail = continuations[0].bounds;
        assert!(
            tail.y > head.y,
            "the continuation belongs to the NEXT row: head {head:?}, tail {tail:?}"
        );
        assert!(
            (tail.x - aligned.x).abs() < 0.001,
            "the continuation starts at the row's left edge: {} vs {}",
            tail.x,
            aligned.x
        );

        // (2) Neither piece extends past the 32-bit row width.
        let row_width = 32.0 * (aligned.width / 16.0);
        for (name, piece) in [("head", head), ("tail", tail)] {
            assert!(
                piece.x + piece.width <= aligned.x + row_width + 0.001,
                "{name} runs past the row's right edge: {} vs {}",
                piece.x + piece.width,
                aligned.x + row_width
            );
        }
        assert!(
            (head.x + head.width - (aligned.x + row_width)).abs() < 0.001,
            "the head fills the row it starts in, ending exactly at the row edge: {head:?}"
        );

        // (3) The pieces still sum to the field's exact bit-proportional width.
        assert!(
            (head.width + tail.width - aligned.width * 2.0).abs() < 0.001,
            "32 bits split across rows must still total twice a 16-bit field: {} + {} vs {}",
            head.width,
            tail.width,
            aligned.width * 2.0
        );

        // (4) A field that does NOT straddle is still exactly one box.
        let plain = layout_diagram_traced_with_algorithm(
            &packet_ir(&[("a", 0, 15), ("b", 16, 31)]),
            LayoutAlgorithm::Packet,
        )
        .layout;
        assert!(
            plain.extensions.packet_field_continuations.is_empty(),
            "row-aligned fields must not be split: {:?}",
            plain.extensions.packet_field_continuations
        );

        // And the continuation is inside the diagram bounds, not clipped.
        assert!(
            layout.bounds.x + layout.bounds.width >= tail.x + tail.width,
            "the continuation must be inside the bounds: bounds end {} < {}",
            layout.bounds.x + layout.bounds.width,
            tail.x + tail.width
        );
    }

    /// A field spanning several whole rows produces one piece per row (bd-8vr0).
    #[test]
    fn packet_layout_splits_a_field_spanning_many_rows() {
        let ir = packet_ir(&[("wide", 16, 111)]);
        let layout = layout_diagram_traced_with_algorithm(&ir, LayoutAlgorithm::Packet).layout;
        let head = layout.nodes[0].bounds;
        let continuations = &layout.extensions.packet_field_continuations;

        // bits 16..111 = 96 bits from mid-row 0 to mid-row 3 => head + 3 continuations.
        assert_eq!(
            continuations.len(),
            3,
            "expected one piece per row after the first: {continuations:?}"
        );
        assert_eq!(
            continuations.iter().map(|c| c.segment).collect::<Vec<_>>(),
            [1, 2, 3],
            "segments are numbered in row order"
        );
        let total: f32 = head.width + continuations.iter().map(|c| c.bounds.width).sum::<f32>();
        let per_bit = head.width / 16.0; // bits 16..31 is the head
        assert!(
            (total - 96.0 * per_bit).abs() < 0.001,
            "the pieces must total the field's 96 bits: {total} vs {}",
            96.0 * per_bit
        );
        assert!(
            continuations
                .windows(2)
                .all(|w| w[1].bounds.y > w[0].bounds.y),
            "each continuation is on a lower row than the last: {continuations:?}"
        );
    }

    /// The `packet-beta` connection form declares no bit ranges, so there is no ruler and the
    /// generic grid stays the honest answer rather than every node collapsing onto bit 0.
    #[test]
    fn packet_layout_without_bit_ranges_falls_back_to_the_grid() {
        let mut ir = MermaidDiagramIr::empty(DiagramType::PacketBeta);
        for id in ["Client", "Gateway", "Backend"] {
            ir.nodes.push(IrNode {
                id: id.to_string(),
                ..IrNode::default()
            });
        }
        let layout = layout_diagram_traced_with_algorithm(&ir, LayoutAlgorithm::Packet).layout;
        assert_eq!(layout.nodes.len(), 3);
        let xs: Vec<f32> = layout.nodes.iter().map(|n| n.bounds.x).collect();
        assert!(
            xs.windows(2).any(|w| (w[0] - w[1]).abs() > 0.001),
            "unranged nodes must not all stack on one x: {xs:?}"
        );
    }

    /// A kanban board has no edges, so its columns must come from the declared lanes. Ranking it
    /// by `layered_ranks` gave every card rank 0 and stacked the whole board in one column
    /// (bd-eg44). Card ids here are deliberately NOT in alphabetical order within a lane, so an id
    /// sort — which is what the shared journey path applies — would fail the ordering assertion.
    #[test]
    fn kanban_layout_columns_come_from_the_declared_lanes() {
        let mut ir = MermaidDiagramIr::empty(DiagramType::Kanban);
        for id in ["todo_z", "todo_a", "doing_z", "doing_a"] {
            ir.nodes.push(IrNode {
                id: id.to_string(),
                ..IrNode::default()
            });
        }
        for (lane, members) in [[0_usize, 1], [2, 3]].into_iter().enumerate() {
            ir.clusters.push(IrCluster {
                id: IrClusterId(lane),
                members: members.map(IrNodeId).to_vec(),
                ..IrCluster::default()
            });
        }

        let layout = layout_diagram_traced_with_algorithm(&ir, LayoutAlgorithm::Kanban).layout;
        let boxes: BTreeMap<&str, LayoutRect> = layout
            .nodes
            .iter()
            .map(|n| (n.node_id.as_str(), n.bounds))
            .collect();

        assert!(
            (boxes["todo_z"].x - boxes["todo_a"].x).abs() < 0.001
                && (boxes["doing_z"].x - boxes["doing_a"].x).abs() < 0.001,
            "cards in one lane share a column: {boxes:?}"
        );
        assert!(
            boxes["doing_z"].x >= boxes["todo_z"].x + boxes["todo_z"].width,
            "different lanes must be separated by at least a card width: {boxes:?}"
        );
        assert!(
            boxes["todo_a"].y > boxes["todo_z"].y && boxes["doing_a"].y > boxes["doing_z"].y,
            "cards stack in DECLARATION order, not id order: {boxes:?}"
        );
        assert!(
            layout.extensions.bands.is_empty(),
            "the lanes are already drawn as cluster boxes with their own titles; a generic \
             \"lane N\" band would be a second rectangle around the same cards"
        );
    }

    /// A card that belongs to no lane still has to be drawn, in a column of its own rather than
    /// silently folded into lane 0.
    #[test]
    fn kanban_layout_gives_a_lane_less_card_its_own_column() {
        let mut ir = MermaidDiagramIr::empty(DiagramType::Kanban);
        for id in ["in_lane", "orphan"] {
            ir.nodes.push(IrNode {
                id: id.to_string(),
                ..IrNode::default()
            });
        }
        ir.clusters.push(IrCluster {
            id: IrClusterId(0),
            members: vec![IrNodeId(0)],
            ..IrCluster::default()
        });

        let layout = layout_diagram_traced_with_algorithm(&ir, LayoutAlgorithm::Kanban).layout;
        let boxes: BTreeMap<&str, LayoutRect> = layout
            .nodes
            .iter()
            .map(|n| (n.node_id.as_str(), n.bounds))
            .collect();
        assert_eq!(boxes.len(), 2, "both cards must be laid out");
        assert!(
            (boxes["orphan"].x - boxes["in_lane"].x).abs() > 0.001,
            "the lane-less card must not land in lane 0's column: {boxes:?}"
        );
    }

    #[test]
    fn kanban_layout_stacks_cards_within_columns() {
        let mut ir = MermaidDiagramIr::empty(DiagramType::Journey);
        for node_id in ["backlog_a", "backlog_b", "doing_a", "doing_b"] {
            ir.nodes.push(IrNode {
                id: node_id.to_string(),
                ..IrNode::default()
            });
        }
        for (from, to) in [(0, 2), (1, 3)] {
            ir.edges.push(IrEdge {
                from: IrEndpoint::Node(IrNodeId(from)),
                to: IrEndpoint::Node(IrNodeId(to)),
                arrow: ArrowType::Arrow,
                ..IrEdge::default()
            });
        }

        let layout = layout_diagram_traced_with_algorithm(&ir, LayoutAlgorithm::Kanban).layout;
        let nodes = layout
            .nodes
            .iter()
            .map(|node| (node.node_id.as_str(), node.bounds.center()))
            .collect::<BTreeMap<_, _>>();

        let backlog_a = nodes.get("backlog_a").expect("backlog_a");
        let backlog_b = nodes.get("backlog_b").expect("backlog_b");
        let doing_a = nodes.get("doing_a").expect("doing_a");
        let doing_b = nodes.get("doing_b").expect("doing_b");

        assert!((backlog_a.x - backlog_b.x).abs() < 0.001);
        assert!(backlog_b.y > backlog_a.y);
        assert!((doing_a.x - doing_b.x).abs() < 0.001);
        assert!(doing_b.y > doing_a.y);
        assert!(doing_a.x > backlog_a.x);
        assert_eq!(layout.extensions.bands.len(), 2);
    }

