    /// A two-state diagram with `note <position> of <target> : <text>` on it.
    fn state_ir_with_note(position: &str, target: &str, text: &str) -> MermaidDiagramIr {
        let mut ir = graph_ir(DiagramType::State, 2, &[(0, 1)]);
        ir.state_notes.push(fm_core::IrStateNote {
            target: target.to_string(),
            position: position.to_string(),
            text: text.to_string(),
            span: Span::default(),
        });
        ir
    }

    /// mermaid's choice/fork example: the `<<choice>>` is a small bare diamond, not a decision box
    /// printed with its id, and a note whose requested side is taken by a neighbour goes to the
    /// free side rather than past the neighbour with its leader through it.
    #[test]
    fn state_choice_is_a_mark_and_notes_keep_clear_of_neighbours() {
        let ir = fm_parser::parse(
            "stateDiagram-v2\n  state if_state <<choice>>\n  [*] --> IsPositive\n  IsPositive --> if_state\n  \
             if_state --> False: if n < 0\n  if_state --> True : if n >= 0\n  state fork_state <<fork>>\n  \
             True --> fork_state\n  fork_state --> State2\n  fork_state --> State3\n  \
             note right of State2 : Important information!\n",
        )
        .ir;
        let layout = layout_diagram(&ir);
        let choice = layout
            .nodes
            .iter()
            .find(|n| n.node_id == "if_state")
            .unwrap();
        assert!(choice.bounds.width <= 32.0 && choice.bounds.height <= 32.0);
        assert_eq!(ir.node_display_text(&ir.nodes[choice.node_index]), "");
        let note = &layout.extensions.state_notes[0];
        let (a, b) = (note.leader_start, note.leader_end);
        for node in layout
            .nodes
            .iter()
            .filter(|n| n.node_index != note.node_index)
        {
            let r = node.bounds;
            let crosses = a.x.max(b.x) > r.x
                && a.x.min(b.x) < r.x + r.width
                && a.y.max(b.y) > r.y
                && a.y.min(b.y) < r.y + r.height;
            assert!(!crosses, "the leader runs through {}", node.node_id);
            assert!(
                !rects_overlap(note.bounds, r),
                "the note covers {}",
                node.node_id
            );
        }
    }

    /// A class diagram's `note "…"` annotates the diagram, not a class: it is placed clear of
    /// every class and every attached note, with no leader, and the canvas holds it.
    #[test]
    fn a_note_on_the_whole_diagram_gets_a_place_of_its_own() {
        let ir = fm_parser::parse(
            "classDiagram\n  note \"From Duck till Zebra\"\n  Animal <|-- Duck\n  Animal <|-- Zebra\n  note for Duck \"can fly\"\n  note \"second\"\n",
        )
        .ir;
        let layout = layout_diagram(&ir);
        let notes = &layout.extensions.state_notes;
        assert_eq!(
            notes.len(),
            3,
            "both free notes and the attached one are placed"
        );
        let free: Vec<_> = notes
            .iter()
            .filter(|n| n.node_index == usize::MAX)
            .collect();
        assert_eq!(
            free.iter().map(|n| n.text.as_str()).collect::<Vec<_>>(),
            ["From Duck till Zebra", "second"]
        );
        for note in &free {
            assert_eq!(note.leader_start, note.leader_end, "nothing to lead to");
            for node in &layout.nodes {
                assert!(
                    !rects_overlap(note.bounds, node.bounds),
                    "covers {}",
                    node.node_id
                );
            }
            for other in notes.iter().filter(|other| !std::ptr::eq(*other, *note)) {
                assert!(
                    !rects_overlap(note.bounds, other.bounds),
                    "covers {:?}",
                    other.text
                );
            }
            let b = layout.bounds;
            assert!(note.bounds.x + note.bounds.width <= b.x + b.width + 0.5);
            assert!(note.bounds.y >= b.y - 0.5);
        }
    }

    /// bd-a6l4: the note must EXIST in the layout at all. Before this, `ir.state_notes` was read by
    /// nothing but `memo_ir_equal`, so a declared note produced no geometry and no output.
    #[test]
    fn state_note_is_placed_beside_its_target() {
        let ir = state_ir_with_note("right", "N1", "This is a note");
        let layout = layout_diagram(&ir);
        assert_eq!(
            layout.extensions.state_notes.len(),
            1,
            "the declared note produced no geometry"
        );
        let note = &layout.extensions.state_notes[0];
        let target = &layout.nodes[1];
        assert_eq!(note.node_index, 1, "note attached to the wrong state");
        assert_eq!(note.text, "This is a note");
        assert!(
            note.bounds.x >= target.bounds.x + target.bounds.width,
            "a `right of` note must start at or past its state's right edge: note.x={:.2} vs \
             target right={:.2}",
            note.bounds.x,
            target.bounds.x + target.bounds.width
        );
        // The leader has to actually span the gap, not be a zero-length stub.
        assert!(
            note.leader_end.x > note.leader_start.x,
            "right-side leader must run left-to-right"
        );
    }

    /// NEGATIVE CASE 2 from bd-a6l4: an implementation that ignores `IrStateNote::position`
    /// passes a right-only test. `left` must land on the OPPOSITE side.
    #[test]
    fn state_note_position_decides_which_side_it_lands_on() {
        let right = layout_diagram(&state_ir_with_note("right", "N1", "note text"));
        let left = layout_diagram(&state_ir_with_note("left", "N1", "note text"));
        let right_note = &right.extensions.state_notes[0];
        let left_note = &left.extensions.state_notes[0];
        assert_eq!(right_note.side, StateNoteSide::Right);
        assert_eq!(left_note.side, StateNoteSide::Left);
        let target = &right.nodes[1];
        assert!(
            left_note.bounds.x + left_note.bounds.width <= target.bounds.x,
            "a `left of` note must end at or before its state's left edge: right edge={:.2} vs \
             target left={:.2}",
            left_note.bounds.x + left_note.bounds.width,
            target.bounds.x
        );
        assert!(
            left_note.bounds.x < right_note.bounds.x,
            "left and right notes coincided at x={:.2} — position was ignored",
            left_note.bounds.x
        );
    }

    /// NEGATIVE CASE 1: the box must RESPOND to the text, and the canvas must grow to hold it.
    ///
    /// Swept over lengths rather than asserted at one, and asserted STRICTLY increasing, so the
    /// test cannot pass by agreeing with a constant — the pre-fix behaviour is no box at all, and a
    /// fixed-width box would fail here too.
    #[test]
    fn state_note_box_and_canvas_grow_with_the_note_text() {
        let mut widths = Vec::new();
        let mut canvas_widths = Vec::new();
        for length in [4_usize, 20, 40, 80, 160] {
            let text = "x".repeat(length);
            let layout = layout_diagram(&state_ir_with_note("right", "N1", &text));
            let note = &layout.extensions.state_notes[0];
            widths.push(note.bounds.width);
            canvas_widths.push(layout.bounds.width);
            let right_edge = note.bounds.x + note.bounds.width;
            let canvas_right = layout.bounds.x + layout.bounds.width;
            assert!(
                right_edge <= canvas_right + 0.01,
                "note of {length} chars runs {:.2}px past the canvas — it would be clipped",
                right_edge - canvas_right
            );
        }
        for pair in widths.windows(2) {
            assert!(
                pair[1] > pair[0],
                "note width did not grow with its text: {widths:?}"
            );
        }
        for pair in canvas_widths.windows(2) {
            assert!(
                pair[1] > pair[0],
                "canvas did not grow with the note: {canvas_widths:?}"
            );
        }
    }

    /// NEGATIVE CASE 3: a state diagram with no notes must be untouched — not "nearly", exactly.
    /// The control is the same diagram WITH a note, which must differ.
    #[test]
    fn a_state_diagram_without_notes_is_unchanged_by_the_note_pass() {
        let plain = layout_diagram(&graph_ir(DiagramType::State, 2, &[(0, 1)]));
        assert!(plain.extensions.state_notes.is_empty());
        let noted = layout_diagram(&state_ir_with_note("right", "N1", "a note"));
        assert_eq!(
            plain.nodes, noted.nodes,
            "adding a note moved the state boxes"
        );
        assert_eq!(
            plain.bounds.height, noted.bounds.height,
            "a side note must not change the diagram height"
        );
        // Control: the note pass DID do something, so the equality above is not vacuous.
        assert!(noted.bounds.width > plain.bounds.width);
    }

    /// NEGATIVE CASE 4: a note whose target does not exist is dropped, not silently reattached to
    /// some other state, and does not panic.
    ///
    /// ⚠️ THE ORPHAN IS PAIRED WITH A VALID NOTE IN THE SAME IR, and that pairing is the whole
    /// design of this test. "Assert the list is empty" passes just as well when the feature is
    /// switched off entirely as when the orphan is correctly rejected — the negative control for
    /// this bead proved exactly that, this test being one of only two that survived disabling the
    /// pass. Placing a resolvable note beside the orphan makes the assertion discriminating: the
    /// list must contain the valid one and ONLY the valid one, which is false both when nothing is
    /// placed and when the orphan is reattached to whatever node came first.
    #[test]
    fn state_note_targeting_an_unknown_state_is_dropped_not_reattached() {
        let mut ir = state_ir_with_note("right", "NoSuchState", "orphan");
        ir.state_notes.push(fm_core::IrStateNote {
            target: "N1".to_string(),
            position: "right".to_string(),
            text: "resolvable".to_string(),
            span: Span::default(),
        });
        let layout = layout_diagram(&ir);
        let placed: Vec<&str> = layout
            .extensions
            .state_notes
            .iter()
            .map(|note| note.text.as_str())
            .collect();
        assert_eq!(
            placed,
            vec!["resolvable"],
            "the orphan note must be dropped and the resolvable one kept"
        );
        // And the canvas must be sized for the note that WAS placed, not for the orphan.
        let orphan_only = layout_diagram(&state_ir_with_note("right", "NoSuchState", "orphan"));
        let plain = layout_diagram(&graph_ir(DiagramType::State, 2, &[(0, 1)]));
        assert_eq!(
            plain.bounds, orphan_only.bounds,
            "an orphan note moved the canvas"
        );
    }

    /// Two notes on the same side of the same state must stack, not coincide — the same defect
    /// class as the force-layout parallel edges pinned in 56a8eafc.
    #[test]
    fn two_notes_on_one_state_stack_instead_of_coinciding() {
        let mut ir = state_ir_with_note("right", "N1", "first note");
        ir.state_notes.push(fm_core::IrStateNote {
            target: "N1".to_string(),
            position: "right".to_string(),
            text: "second note".to_string(),
            span: Span::default(),
        });
        let layout = layout_diagram(&ir);
        assert_eq!(layout.extensions.state_notes.len(), 2);
        let (first, second) = (
            &layout.extensions.state_notes[0],
            &layout.extensions.state_notes[1],
        );
        assert!(
            second.bounds.y >= first.bounds.y + first.bounds.height,
            "two notes on one state overlapped: first y={:.2} h={:.2}, second y={:.2}",
            first.bounds.y,
            first.bounds.height,
            second.bounds.y
        );
        assert_eq!(
            second.leader_end.y,
            second.bounds.center().y,
            "the displaced note's leader must reach its own box"
        );
        assert_ne!(first.leader_end, second.leader_end);
    }

    #[test]
    fn multiline_notes_on_adjacent_states_do_not_cover_each_other() {
        let lines = (1..=12)
            .map(|line| format!("    Detail {line}\n"))
            .collect::<String>();
        for side in ["left", "right"] {
            let source = format!(
                "stateDiagram-v2\n  A --> B\n  note {side} of A\n{lines}  end note\n  note {side} of B\n{lines}  end note\n"
            );
            let ir = fm_parser::parse(&source).ir;
            let layout = layout_diagram(&ir);
            let notes = &layout.extensions.state_notes;
            assert_eq!(notes.len(), 2);
            assert!(
                !rects_overlap(notes[0].bounds, notes[1].bounds),
                "{side}: notes on adjacent states overlap"
            );
            for note in notes {
                assert_eq!(note.leader_end.y, note.bounds.center().y);
                for node in &layout.nodes {
                    assert!(!rects_overlap(note.bounds, node.bounds));
                }
                assert!(note.bounds.x.is_finite() && note.bounds.y.is_finite());
                assert!(note.bounds.y >= layout.bounds.y);
                assert!(
                    note.bounds.y + note.bounds.height
                        <= layout.bounds.y + layout.bounds.height + 0.5
                );
            }
            assert_eq!(
                *notes,
                layout_diagram(&ir).extensions.state_notes,
                "placement must be deterministic"
            );
        }
    }

    #[test]
    fn stacked_state_and_class_notes_clear_nodes_in_their_new_rows() {
        for diagram_type in [DiagramType::State, DiagramType::Class] {
            for side in ["left", "right"] {
                let mut ir = graph_ir(diagram_type, 3, &[(0, 1), (1, 2)]);
                for text in ["first note", "second note"] {
                    ir.state_notes.push(fm_core::IrStateNote {
                        target: "N0".to_string(),
                        position: side.to_string(),
                        text: text.to_string(),
                        span: Span::default(),
                    });
                }
                // The initial row is clear. Stacking the second note enters the first lower
                // node; clearing that node enters the next one, requiring another clearance pass.
                let obstacle_x = if side == "left" { -200.0 } else { 112.0 };
                let nodes: Vec<_> = [
                    LayoutRect {
                        x: 0.0,
                        y: 0.0,
                        width: 80.0,
                        height: 40.0,
                    },
                    LayoutRect {
                        x: obstacle_x,
                        y: 45.0,
                        width: 168.0,
                        height: 60.0,
                    },
                    LayoutRect {
                        x: obstacle_x,
                        y: 110.0,
                        width: 168.0,
                        height: 30.0,
                    },
                ]
                .into_iter()
                .enumerate()
                .map(|(index, bounds)| LayoutNodeBox {
                    node_index: index,
                    node_id: format!("N{index}"),
                    rank: index,
                    order: 0,
                    span: Span::default(),
                    bounds,
                })
                .collect();
                let notes =
                    super::build_state_note_geometry(&ir, &nodes, &fm_core::FontMetrics::default());
                assert_eq!(notes.len(), 2);
                assert!(notes[0].bounds.y + notes[0].bounds.height < nodes[1].bounds.y);
                assert!(notes[1].bounds.y >= nodes[2].bounds.y + nodes[2].bounds.height);
                assert!(!rects_overlap(notes[0].bounds, notes[1].bounds));
                for note in &notes {
                    for node in &nodes {
                        assert!(!rects_overlap(note.bounds, node.bounds));
                    }
                    let edge_x = match note.side {
                        StateNoteSide::Left => note.bounds.x + note.bounds.width,
                        StateNoteSide::Right => note.bounds.x,
                    };
                    assert_eq!(note.leader_end.x, edge_x);
                    assert_eq!(note.leader_end.y, note.bounds.center().y);
                    assert_eq!(note.leader_start.y, nodes[0].bounds.center().y);
                }
            }
        }
    }

    /// Edge list of `golden/cycle_ladder.mmd`, the fixture with the most measured crossings.
    ///
    /// Two parallel spines, rungs in BOTH directions between them, and four back edges. Nodes are
    /// `N0..N4` for the left spine and `N5..N9` for the right, in the fixture's declaration order.
    const LADDER_EDGES: [(usize, usize); 22] = [
        (0, 1),
        (1, 2),
        (2, 3),
        (3, 4),
        (5, 6),
        (6, 7),
        (7, 8),
        (8, 9),
        (0, 5),
        (5, 0),
        (1, 6),
        (6, 1),
        (2, 7),
        (7, 2),
        (3, 8),
        (8, 3),
        (4, 9),
        (9, 4),
        (2, 0),
        (8, 6),
        (4, 1),
        (9, 5),
    ];

    /// Deepest penetration of any routed edge into a node box that is NOT one of its endpoints.
    ///
    /// Returns `(edge_index, node_index, depth)` for the worst offender. Depth is the distance from
    /// the deepest sampled point to the NEAREST box edge, so a value near half the box height means
    /// the edge runs through the middle of the node rather than clipping a corner.
    ///
    /// Samples the routed POLYLINE, which is what layout owns. The SVG backend smooths these points
    /// into a curve, so the rendered path can bulge slightly further; measuring the polyline keeps
    /// this a claim about layout and nothing else.
    fn deepest_edge_incursion(
        layout: &DiagramLayout,
        edges: &[(usize, usize)],
    ) -> Option<(usize, usize, f32)> {
        let mut worst: Option<(usize, usize, f32)> = None;
        for path in &layout.edges {
            let Some(&(source, target)) = edges.get(path.edge_index) else {
                continue;
            };
            for node in &layout.nodes {
                if node.node_index == source || node.node_index == target {
                    continue;
                }
                let rect = node.bounds;
                for window in path.points.windows(2) {
                    let (a, b) = (window[0], window[1]);
                    // 24 samples per segment: fine enough that a segment clipping a corner is seen,
                    // coarse enough to stay cheap on a 22-edge graph.
                    for step in 0..=24_u8 {
                        let t = f32::from(step) / 24.0;
                        let x = (b.x - a.x).mul_add(t, a.x);
                        let y = (b.y - a.y).mul_add(t, a.y);
                        let dx = (x - rect.x).min(rect.x + rect.width - x);
                        let dy = (y - rect.y).min(rect.y + rect.height - y);
                        if dx > 0.0 && dy > 0.0 {
                            let depth = dx.min(dy);
                            if worst.is_none_or(|(_, _, best)| depth > best) {
                                worst = Some((path.edge_index, node.node_index, depth));
                            }
                        }
                    }
                }
            }
        }
        worst
    }

    /// bd-h2ze: a routed edge must not run through a node it does not connect to.
    ///
    /// This dense ladder dispatches to force layout. Its closely packed boxes can block every
    /// corridor between two endpoint faces: returning an obstructed midpoint sent edge 1 through
    /// N9 by 22.88px. The bounded retry must search outside that strip while protecting its own
    /// endpoint boxes too. Keep the original 4px tolerance, which permits grazing a border but
    /// rejects a connection running through another node.
    #[test]
    fn routed_edges_do_not_run_through_unrelated_nodes() {
        let ir = graph_ir(DiagramType::Flowchart, 10, &LADDER_EDGES);
        let layout = layout_diagram(&ir);
        let worst = deepest_edge_incursion(&layout, &LADDER_EDGES);
        assert!(
            worst.is_none_or(|(_, _, depth)| depth <= 4.0),
            "an edge is routed through a node it does not connect to: {worst:?} \
             (edge_index, node_index, penetration_px)"
        );
    }

    /// A note must clear every state box its own row runs into, not just its target's.
    ///
    /// Fixture is a fan-out, so `N1` and `N2` share a rank and sit side by side; a note on `N1`
    /// placed only relative to `N1` lands on top of `N2`. Asserted against EVERY node box, so the
    /// test states the property (no overlap) rather than the fixture's particular geometry.
    #[test]
    fn a_state_note_clears_the_other_states_on_its_row() {
        let mut ir = graph_ir(DiagramType::State, 3, &[(0, 1), (0, 2)]);
        ir.state_notes.push(fm_core::IrStateNote {
            target: "N1".to_string(),
            position: "right".to_string(),
            text: "a note long enough to reach its neighbour".to_string(),
            span: Span::default(),
        });
        let layout = layout_diagram(&ir);
        let note = &layout.extensions.state_notes[0];
        for node in &layout.nodes {
            let overlap_x = (note.bounds.x + note.bounds.width)
                .min(node.bounds.x + node.bounds.width)
                - note.bounds.x.max(node.bounds.x);
            let overlap_y = (note.bounds.y + note.bounds.height)
                .min(node.bounds.y + node.bounds.height)
                - note.bounds.y.max(node.bounds.y);
            assert!(
                overlap_x <= 0.0 || overlap_y <= 0.0,
                "the note overlaps state {} by {overlap_x:.2}x{overlap_y:.2}",
                node.node_id
            );
        }
    }

    /// A note on a FLOWCHART-typed IR must produce nothing even if the field is populated: the pass
    /// is gated on the diagram type, so no other diagram type can be moved by it.
    ///
    /// ⚠️ Same trap as the orphan test: "the flowchart has no notes" is also true when the pass is
    /// off, so the SAME note is fed to a State-typed IR as a live control. The type gate is only
    /// demonstrated if one produces geometry and the other does not.
    #[test]
    fn state_note_geometry_is_confined_to_state_diagrams() {
        let populate = |diagram_type| {
            let mut ir = graph_ir(diagram_type, 2, &[(0, 1)]);
            ir.state_notes.push(fm_core::IrStateNote {
                target: "N1".to_string(),
                position: "right".to_string(),
                text: "drawn for state diagrams only".to_string(),
                span: Span::default(),
            });
            layout_diagram(&ir)
        };
        let flowchart = populate(DiagramType::Flowchart);
        let state = populate(DiagramType::State);
        assert!(
            flowchart.extensions.state_notes.is_empty(),
            "a flowchart was given state-note geometry"
        );
        assert_eq!(
            state.extensions.state_notes.len(),
            1,
            "CONTROL FAILED: the identical note produced nothing on a state diagram either, so \
             this test proves nothing about the type gate"
        );
        let plain = layout_diagram(&graph_ir(DiagramType::Flowchart, 2, &[(0, 1)]));
        assert_eq!(plain.bounds, flowchart.bounds);
    }

    /// Two renders of the SAME document must not disagree because the host was busy (bd-ryxg).
    ///
    /// `MermaidBudgetLedger::record_parse` takes MEASURED parse wall time, and the ledger
    /// rebalances its stage split from it. When the guardrail triple was read off that rebalanced
    /// split, a nominal-tier host gave `max_layout_time_ms` 180 for a 10ms parse and 37 for a
    /// 200ms parse — and this document's Sugiyama estimate sits between them, so the two arms
    /// selected different algorithms and produced different geometry from identical input.
    ///
    /// The last block is the control: it lays the same document out under the two guardrail
    /// triples the old rule actually produced, and requires them to disagree. Without it the
    /// equality assertions could pass vacuously on a document no guardrail can influence.
    ///
    /// The algorithm is requested explicitly rather than left to `Auto` so the test measures the
    /// guardrail, not the auto-selector's heuristics: `dispatch_layout_algorithm` honours an
    /// explicit request, and `evaluate_layout_guardrails` then applies the budget to it exactly as
    /// it does for an auto-selected one.
    ///
    /// SIZING — a starved budget alone does not change the algorithm. `evaluate_layout_guardrails`
    /// only moves off the requested algorithm when a *fallback candidate* is itself within budget
    /// (or scores lower); when every candidate breaches too, it keeps the original and reports
    /// `guardrail_forced_*`. So the document has to make one candidate cheap, and a 24-node
    /// directed path does: `estimate_layout_cost` prices `Tree` on its path specialization
    /// (ceil(24/16) + ceil(23/16) + 1 = 5ms, 24+4 = 28 iterations, 23*8 + 24 = 208 route ops)
    /// while `Sugiyama` costs 24*23/50 + ceil(24/4)*5 + 10 = 52ms, 84 iterations and
    /// 23*24 + 24*4 = 648 route ops. Against the two triples the old rule produced, that gives
    /// Sugiyama inside the 10ms-parse budget (180/144/2880) and outside the 200ms-parse one
    /// (37/30/592) on all three axes, with Tree inside both — so the guardrail really does swap
    /// the algorithm, which is what the control below requires.
    #[test]
    fn measured_parse_time_does_not_change_the_layout_of_the_same_document() {
        let edges: Vec<(usize, usize)> = (0..23).map(|i| (i, i + 1)).collect();
        let ir = graph_ir(DiagramType::Flowchart, 24, &edges);
        let pressure = MermaidPressureReport {
            tier: MermaidPressureTier::Nominal,
            telemetry_available: true,
            ..MermaidPressureReport::default()
        };
        let arm = |parse_ms: u64| {
            let mut broker = MermaidBudgetLedger::new(&pressure);
            broker.record_parse(parse_ms);
            let guardrails = LayoutGuardrails::from(&broker);
            (
                guardrails,
                layout_diagram_traced_with_algorithm_and_guardrails(
                    &ir,
                    LayoutAlgorithm::Sugiyama,
                    guardrails,
                ),
            )
        };

        let (fast_guardrails, fast) = arm(10);
        let (slow_guardrails, slow) = arm(200);
        assert_eq!(
            fast_guardrails, slow_guardrails,
            "guardrails moved with measured parse time"
        );
        assert_eq!(
            fast.trace.guard.selected_algorithm, slow.trace.guard.selected_algorithm,
            "a slow parse selected a different layout algorithm for the same document"
        );
        assert_eq!(
            fast.layout, slow.layout,
            "a slow parse produced different geometry for the same document"
        );

        // CONTROL — the guardrail span measured parse time used to produce, laid out directly.
        //
        // These two triples are what the OLD rule handed this exact document: the ledger's
        // post-parse rebalance gave layout 250-10 = 240, minus a ceil(240/4) render tail, i.e.
        // 180ms for a 10ms parse; and 250-200 = 50, minus ceil(50/4), i.e. 37ms for a 200ms parse.
        // The iteration and route budgets scale with that share. Laying the same document out
        // under both proves the span was not cosmetic — it changed the chosen algorithm — which is
        // what makes the equality assertions above worth making. Without this the test could pass
        // vacuously on a document no guardrail can influence.
        let under = |guardrails: LayoutGuardrails| {
            layout_diagram_traced_with_algorithm_and_guardrails(
                &ir,
                LayoutAlgorithm::Sugiyama,
                guardrails,
            )
        };
        let old_fast_parse = under(LayoutGuardrails {
            max_layout_time_ms: 180,
            max_layout_iterations: 144,
            max_route_ops: 2_880,
        });
        let old_slow_parse = under(LayoutGuardrails {
            max_layout_time_ms: 37,
            max_layout_iterations: 30,
            max_route_ops: 592,
        });
        assert_ne!(
            old_fast_parse.trace.guard.selected_algorithm,
            old_slow_parse.trace.guard.selected_algorithm,
            "control failed: measured parse time no longer spans a guardrail range that changes \
             this document's algorithm, so the equality assertions above prove nothing. \
             fast triple: reason={} estimate={}ms/{}it/{}ops; slow triple: reason={} \
             estimate={}ms/{}it/{}ops — a `guardrail_forced_*` reason on the slow arm means every \
             fallback candidate breached the budget too, so the guardrail kept the requested \
             algorithm and the document needs resizing, not the assertion relaxing",
            old_fast_parse.trace.guard.reason,
            old_fast_parse.trace.guard.estimated_layout_time_ms,
            old_fast_parse.trace.guard.estimated_layout_iterations,
            old_fast_parse.trace.guard.estimated_route_ops,
            old_slow_parse.trace.guard.reason,
            old_slow_parse.trace.guard.estimated_layout_time_ms,
            old_slow_parse.trace.guard.estimated_layout_iterations,
            old_slow_parse.trace.guard.estimated_route_ops,
        );
    }

    fn layout_with_constraints(ir: &MermaidDiagramIr) -> DiagramLayout {
        layout_diagram_with_config(
            ir,
            LayoutConfig {
                constraint_solver: ConstraintSolverMode::Optimize,
                ..LayoutConfig::default()
            },
        )
    }

    fn node_bounds<'a>(layout: &'a DiagramLayout, node_id: &str) -> &'a LayoutRect {
        &layout
            .nodes
            .iter()
            .find(|node| node.node_id == node_id)
            .unwrap()
            .bounds
    }

    /// An LP result is written into coordinates ONLY when it is a proven optimum (bd-9xwk).
    ///
    /// This is the deterministic half of the fix, and the half the end-to-end probe below cannot
    /// reach. `model.solve()` returning `Ok` does not mean solved: good_lp's HiGHS backend maps
    /// every budget stop onto `SolutionStatus::TimeLimit` and still returns `Ok` whenever a feasible
    /// primal point exists, and the old code — which checked only for `Err` — wrote that point
    /// straight into `node.bounds`.
    ///
    /// Asserted on the decision itself because it cannot be provoked through a layout: a valve short
    /// enough to fire deterministically stops HiGHS before it has a feasible point at all, so
    /// good_lp returns `Err` and the caller falls back for a different reason. I confirmed that by
    /// running the end-to-end probe with this predicate disabled — it still passed, i.e. it is
    /// VACUOUS for this branch. Provoking a genuine feasible-but-suboptimal stop means interrupting
    /// phase 2 of the simplex, which is a race and has no place in a test.
    /// The LP's operative stop is counted, so it lands in the same place on every machine (bd-4q4d).
    ///
    /// A wall clock cannot do this job: whether a solve fits inside it depends on the box, so with
    /// only a clock the CHOICE between proven optimum and heuristic fallback stays a function of
    /// host load even when each branch is itself deterministic. A simplex iteration is the same unit
    /// of work everywhere.
    #[test]
    #[cfg(feature = "highs")]
    fn constraint_lp_iteration_bound_is_a_pure_function_of_problem_size() {
        // Deterministic: the same problem shape always gets the same bound, on any machine.
        assert_eq!(
            constraint_lp_iteration_limit(120, 3),
            constraint_lp_iteration_limit(120, 3)
        );
        // Sized from the problem, and strictly so on both axes.
        assert!(constraint_lp_iteration_limit(240, 3) > constraint_lp_iteration_limit(120, 3));
        assert!(constraint_lp_iteration_limit(120, 9) > constraint_lp_iteration_limit(120, 3));
        // Headroom no correct solve uses: simplex on this shape converges in O(rows).
        assert_eq!(constraint_lp_iteration_limit(120, 3), (120 * 4 + 3) * 64);
        // Clamped, and the clamp cannot overflow i32 or depend on anything but the input.
        assert_eq!(
            constraint_lp_iteration_limit(usize::MAX, usize::MAX),
            2_000_000
        );
        assert_eq!(constraint_lp_iteration_limit(0, 0), 0);
    }

    #[test]
    fn constraint_lp_result_is_used_only_when_proven_optimal() {
        assert!(
            constraint_solution_is_usable(SolutionStatus::Optimal),
            "a proven optimum is the one result that may become geometry"
        );
        assert!(
            !constraint_solution_is_usable(SolutionStatus::TimeLimit),
            "a budget-stopped solve carries a feasible-but-suboptimal point and must be refused; \
             good_lp reports it as Ok, so nothing upstream of this check would catch it"
        );
        assert!(
            !constraint_solution_is_usable(SolutionStatus::GapLimit),
            "a gap-limited solve is not a proven optimum either"
        );
    }

    /// The LP's wall-clock valve must never reach the coordinates (bd-9xwk).
    ///
    /// `model.solve()` returning `Ok` does not mean "solved": HiGHS answers a budget stop with
    /// `ReachedTimeLimit` and, whenever a feasible primal point exists, good_lp hands that
    /// suboptimal point back as `Ok`. Before the status check, those coordinates went straight into
    /// `node.bounds`, so the same document rendered differently depending on how busy the host was
    /// — on the DEFAULT path, since `ConstraintSolverMode::Optimize` is `#[default]` and the DOT
    /// bridge populates `ir.constraints` from ordinary `rank=same` / `minlen`.
    ///
    /// The probe starves the valve rather than trusting a quiet host, because a budget that never
    /// binds is invisible to any test that does not starve it (the lesson from bd-9a1t's probe 2
    /// control and bd-giej).
    #[test]
    fn constraint_solver_wall_clock_valve_never_reaches_the_coordinates() {
        // A LAYERED DAG, not a chain, and laid out through an EXPLICIT Sugiyama request with the
        // guardrails lifted. Both details are load-bearing and cost me a run to learn:
        // `apply_constraint_solver` is called from ONE place — inside
        // `layout_diagram_sugiyama_traced_with_config` — so a document that the guardrail diverts
        // to Tree, or that the directed-path specialization claims, never reaches the LP at all,
        // and the control below correctly reported the fixture rather than the fix.
        const NODES: usize = 120;
        const WIDTH: usize = 8;
        let edges: Vec<(usize, usize)> = (0..NODES - WIDTH).map(|i| (i, i + WIDTH)).collect();
        let mut ir = labeled_graph_ir(NODES, &edges);
        ir.constraints.push(IrConstraint::SameRank {
            node_ids: (0..NODES)
                .step_by(WIDTH + 3)
                .map(|i| format!("N{i}"))
                .collect(),
            span: Span::default(),
        });
        ir.constraints.push(IrConstraint::MinLength {
            from_id: "N0".to_string(),
            to_id: format!("N{}", NODES - 1),
            min_len: 9,
            span: Span::default(),
        });
        // A pin is the most forceful constraint there is — an equality to an absolute coordinate —
        // so it doubles as the reachability check below. If the LP runs at all, N5 lands here.
        ir.constraints.push(IrConstraint::Pin {
            node_id: "N5".to_string(),
            x: 1_500.0,
            y: 900.0,
            span: Span::default(),
        });

        let guardrails = LayoutGuardrails {
            max_layout_time_ms: 600_000,
            max_layout_iterations: 1_000_000,
            max_route_ops: 100_000_000,
        };
        let lay = |solver: ConstraintSolverMode, valve_ms: u64| {
            layout_diagram_traced_with_config_and_guardrails(
                &ir,
                LayoutAlgorithm::Sugiyama,
                LayoutConfig {
                    constraint_solver: solver,
                    constraint_solver_wall_clock_valve_ms: valve_ms,
                    ..LayoutConfig::default()
                },
                guardrails,
            )
            .layout
            .nodes
            .clone()
        };
        let heuristic = lay(
            ConstraintSolverMode::Disabled,
            CONSTRAINT_SOLVER_WALL_CLOCK_VALVE_MS,
        );
        let solved = lay(
            ConstraintSolverMode::Optimize,
            CONSTRAINT_SOLVER_WALL_CLOCK_VALVE_MS,
        );

        // REACHABILITY CHECK, separate from the control so a failure says WHICH thing is wrong.
        // `apply_constraint_solver` has exactly one caller, inside
        // `layout_diagram_sugiyama_traced_with_config`, so a document routed anywhere else never
        // reaches the LP. If the pin did not land, the fixture is not reaching the solver and no
        // conclusion about the valve can be drawn from anything below.
        let pinned = solved
            .iter()
            .find(|node| node.node_id == "N5")
            .expect("N5 is in the layout");
        assert!(
            (pinned.bounds.x - 1_500.0).abs() < 1.0 && (pinned.bounds.y - 900.0).abs() < 1.0,
            "the LP never ran for this fixture: N5 is pinned to (1500, 900) but sits at ({}, {}), \
             so this document is not being routed through the Sugiyama path that calls \
             apply_constraint_solver",
            pinned.bounds.x,
            pinned.bounds.y
        );

        // CONTROL. If the LP does not move this document, "solved" and "heuristic" are the same
        // value, every assertion below holds for free, and the probe proves nothing.
        assert_ne!(
            solved, heuristic,
            "control failed: the LP does not move this document, so a fired valve and a solved LP \
             are indistinguishable here"
        );

        // THE FAIL-CLOSED PATH, exercised deterministically rather than by racing the solver. A
        // valve of zero cannot be met by any machine, so HiGHS stops without a proven optimum, and
        // the coordinates must be exactly the untouched heuristic ones. Before the status check
        // this returned whatever feasible point the solver happened to be holding.
        assert_eq!(
            lay(ConstraintSolverMode::Optimize, 0),
            heuristic,
            "a valve that cannot be met must leave the heuristic coordinates untouched, not write \
             out whatever partial solution the LP had reached"
        );

        // THE PROPERTY. Across four orders of magnitude of valve — every one of which leaves the
        // problem itself untouched — the coordinates are only ever the proven optimum or the
        // deterministic heuristic fallback. A third geometry is a partially-optimized solution
        // that reached the output, which is the defect.
        for valve_ms in [1_u64, 2, 5, 25, 250, CONSTRAINT_SOLVER_WALL_CLOCK_VALVE_MS] {
            let nodes = lay(ConstraintSolverMode::Optimize, valve_ms);
            assert!(
                nodes == solved || nodes == heuristic,
                "valve {valve_ms}ms produced a third geometry: neither the proven optimum nor the \
                 heuristic fallback, i.e. coordinates chosen by how much clock the solver got"
            );
        }
    }

    #[test]
    fn constraint_solver_keeps_unconstrained_layouts_identical() {
        let ir = labeled_graph_ir(4, &[(0, 2), (1, 2), (2, 3)]);
        let optimized = layout_with_constraints(&ir);
        let disabled = layout_diagram_with_config(
            &ir,
            LayoutConfig {
                constraint_solver: ConstraintSolverMode::Disabled,
                ..LayoutConfig::default()
            },
        );
        assert_eq!(optimized, disabled);
    }

    /// Layout with the solver on, and the same layout with it off, for one IR.
    ///
    /// Every fault test below is "does the engine fall back CLEANLY", and the only honest way to
    /// say "fell back" is that the coordinates equal the solver-disabled ones exactly.
    fn constrained_and_heuristic(ir: &MermaidDiagramIr) -> (DiagramLayout, DiagramLayout) {
        (
            layout_with_constraints(ir),
            layout_diagram_with_config(
                ir,
                LayoutConfig {
                    constraint_solver: ConstraintSolverMode::Disabled,
                    ..LayoutConfig::default()
                },
            ),
        )
    }

    /// An LP that cannot be satisfied must fall back, not panic and not half-apply (bd-1s1g.3).
    ///
    /// `MinLength` A->B and B->A on the same axis demand `y_B - y_A >= g` and `y_A - y_B >= g` with
    /// both gaps positive, which is infeasible. good_lp maps HiGHS `Infeasible` to
    /// `ResolutionError::Infeasible`, `solve_constraint_coordinates` propagates it, and
    /// `apply_constraint_solver` takes its `layout.constraint_solver.fallback` branch leaving the
    /// heuristic coordinates untouched.
    #[test]
    fn contradictory_constraints_fall_back_to_the_heuristic_layout() {
        let mut ir = labeled_graph_ir(6, &[(0, 1), (1, 2), (2, 3), (3, 4), (4, 5)]);
        // min_len 12 rather than 3: min_length_gap is (height + rank_spacing) * min_len, and a
        // six-node chain already separates N1 from N4 by about three of those, so min_len 3 sits
        // right on the boundary. A control that only marginally forces movement is a bad control.
        ir.constraints.push(IrConstraint::MinLength {
            from_id: "N1".to_string(),
            to_id: "N4".to_string(),
            min_len: 12,
            span: Span::default(),
        });
        ir.constraints.push(IrConstraint::MinLength {
            from_id: "N4".to_string(),
            to_id: "N1".to_string(),
            min_len: 12,
            span: Span::default(),
        });

        let (constrained, heuristic) = constrained_and_heuristic(&ir);
        assert_eq!(
            constrained.nodes, heuristic.nodes,
            "an infeasible LP must leave the heuristic coordinates exactly as they were, not \
             half-apply a partial solution"
        );

        // CONTROL. Drop the contradiction and the solver moves this document, so the equality above
        // is a statement about infeasibility rather than about a graph the solver ignores.
        ir.constraints.pop();
        let (satisfiable, heuristic_again) = constrained_and_heuristic(&ir);
        assert_ne!(
            satisfiable.nodes, heuristic_again.nodes,
            "control failed: the solver does not move this document even when the constraints are \
             satisfiable, so the fallback assertion proves nothing"
        );
    }

    /// The fallback must be DETERMINISTIC, because that is the whole point of bd-9xwk.
    #[test]
    fn infeasible_constraint_fallback_is_deterministic() {
        let mut ir = labeled_graph_ir(5, &[(0, 1), (1, 2), (2, 3), (3, 4)]);
        ir.constraints.push(IrConstraint::Pin {
            node_id: "N1".to_string(),
            x: 10.0,
            y: 40.0,
            span: Span::default(),
        });
        ir.constraints.push(IrConstraint::Pin {
            node_id: "N1".to_string(),
            x: 900.0,
            y: 700.0,
            span: Span::default(),
        });

        let first = layout_with_constraints(&ir);
        let second = layout_with_constraints(&ir);
        assert_eq!(
            first.nodes, second.nodes,
            "two runs of the same contradictory document must agree; a fallback that varies is the \
             load-dependence bd-9xwk removed"
        );
    }

    #[test]
    fn diagnose_constraint_infeasibility_identifies_minimal_conflicting_subset() {
        let mut ir = labeled_graph_ir(4, &[(0, 1), (1, 2), (2, 3)]);
        // Benign constraint at index 0
        ir.constraints.push(IrConstraint::Pin {
            node_id: "N0".to_string(),
            x: 20.0,
            y: 20.0,
            span: Span::at_line(2, 1),
        });
        // Mutually conflicting pins on N1 at indices 1 and 2
        ir.constraints.push(IrConstraint::Pin {
            node_id: "N1".to_string(),
            x: 10.0,
            y: 40.0,
            span: Span::at_line(3, 5),
        });
        ir.constraints.push(IrConstraint::Pin {
            node_id: "N1".to_string(),
            x: 900.0,
            y: 700.0,
            span: Span::at_line(4, 5),
        });

        let base_layout = layout_diagram_with_config(
            &ir,
            LayoutConfig {
                constraint_solver: ConstraintSolverMode::Disabled,
                ..LayoutConfig::default()
            },
        );
        let (report, description) = super::diagnose_constraint_infeasibility(
            &ir,
            &base_layout.nodes,
            LayoutSpacing::default(),
            CONSTRAINT_SOLVER_WALL_CLOCK_VALVE_MS,
        )
        .expect("contradictory pins on N1 must be diagnosed as infeasible");

        assert_eq!(report.conflicting, vec![1, 2]);
        assert_eq!(
            report.first_conflicting_span(&ir.constraints),
            Some(Span::at_line(3, 5))
        );
        assert!(description.contains("N1 pinned to (10, 40)"));
        assert!(description.contains("N1 pinned to (900, 700)"));
        assert!(!description.contains("N0"));
    }

    #[test]
    fn polyhedral_tiled_sweeps_and_spectral_partitioning_orchestrate_end_to_end() {
        let ir = labeled_graph_ir(
            8,
            &[
                (0, 3),
                (1, 2),
                (2, 5),
                (3, 4),
                (4, 7),
                (5, 6),
                (0, 2),
                (1, 3),
            ],
        );
        let cycles = super::CycleRemovalResult::default();
        let priorities = super::stable_node_priorities(&ir);
        let ranks = super::rank_assignment(&ir, &cycles, &priorities);
        let initial_order = super::nodes_by_rank(ir.nodes.len(), &ranks);
        let initial_crossings = super::total_crossings(&ir, &ranks, &initial_order);

        let (tiled_crossings, tiled_order, schedule) = super::execute_tiled_barycenter_sweeps(
            &ir,
            &ranks,
            initial_order,
            4,
            &LayoutConfig::default(),
        );
        assert!(
            tiled_crossings <= initial_crossings,
            "tiled barycenter sweeps must not increase crossings ({tiled_crossings} vs {initial_crossings})"
        );
        assert_eq!(schedule.num_layers, tiled_order.len());
        assert_eq!(schedule.total_iterations(), tiled_order.len() * 4);

        let small_cfg = super::spectral::SpectralConfig {
            min_nodes: 20,
            ..super::spectral::SpectralConfig::default()
        };
        assert!(super::partition_diagram_spectrally(&ir, &small_cfg).is_none());

        let active_cfg = super::spectral::SpectralConfig {
            min_nodes: 4,
            target_partitions: 2,
            balance_threshold: 0.25,
            max_depth: 2,
        };
        let decomp = super::partition_diagram_spectrally(&ir, &active_cfg)
            .expect("8-node graph should partition when min_nodes = 4");
        assert_eq!(decomp.result.partitions.len(), 2);
        assert_eq!(decomp.mapping.global_to_partition.len(), 8);
        let covered: usize = decomp.mapping.partitions.iter().map(Vec::len).sum();
        assert_eq!(covered, 8);
    }

    /// A constraint naming a node that does not exist must be skipped, not panic (bd-1s1g.3).
    #[test]
    fn constraints_on_unknown_nodes_are_skipped_without_panicking() {
        let mut ir = labeled_graph_ir(4, &[(0, 1), (1, 2), (2, 3)]);
        ir.constraints.push(IrConstraint::MinLength {
            from_id: "GHOST_FROM".to_string(),
            to_id: "N2".to_string(),
            min_len: 2,
            span: Span::default(),
        });
        ir.constraints.push(IrConstraint::Pin {
            node_id: "ALSO_MISSING".to_string(),
            x: 5.0,
            y: 5.0,
            span: Span::default(),
        });
        ir.constraints.push(IrConstraint::SameRank {
            node_ids: vec!["N0".to_string(), "NOT_A_NODE".to_string()],
            span: Span::default(),
        });

        let (constrained, heuristic) = constrained_and_heuristic(&ir);
        // Every resolvable constraint here degenerates to nothing (SameRank over one real node
        // constrains nothing), so the layout must be exactly the heuristic one — and above all the
        // engine must not have panicked reaching that conclusion.
        assert_eq!(constrained.nodes, heuristic.nodes);
        assert_eq!(constrained.nodes.len(), 4);
    }

    /// Degenerate inputs must not reach the solver at all (bd-1s1g.3).
    #[test]
    fn degenerate_inputs_skip_the_solver_entirely() {
        // No constraints: the guard is `ir.constraints.is_empty()`.
        let plain = labeled_graph_ir(3, &[(0, 1), (1, 2)]);
        let (constrained, heuristic) = constrained_and_heuristic(&plain);
        assert_eq!(constrained.nodes, heuristic.nodes);

        // No nodes: the guard is `nodes.is_empty()`, reached with a constraint present so the
        // earlier guard cannot be the one doing the work.
        let mut empty = labeled_graph_ir(0, &[]);
        empty.constraints.push(IrConstraint::Pin {
            node_id: "N0".to_string(),
            x: 1.0,
            y: 1.0,
            span: Span::default(),
        });
        let empty_layout = layout_with_constraints(&empty);
        assert!(empty_layout.nodes.is_empty());

        // One node, one pin: the smallest problem the solver can actually be handed.
        let mut single = labeled_graph_ir(1, &[]);
        single.constraints.push(IrConstraint::Pin {
            node_id: "N0".to_string(),
            x: 320.0,
            y: 24.0,
            span: Span::default(),
        });
        let solved = layout_with_constraints(&single);
        let pinned = node_bounds(&solved, "N0");
        assert!((pinned.x - 320.0).abs() < 1.0 && (pinned.y - 24.0).abs() < 1.0);
    }

    /// Extreme coefficients must not produce non-finite geometry (bd-1s1g.3).
    ///
    /// Coordinates are `f32` in the layout and `f64` in the LP, so a 1e15 pin is representable but
    /// far outside any real diagram. Whatever the solver decides, nothing downstream may receive a
    /// NaN or an infinity — those propagate through every later geometry pass silently.
    #[test]
    fn extreme_constraint_magnitudes_keep_coordinates_finite() {
        for (x, y) in [(1e15_f64, -1e15_f64), (1e-15, 1e-15), (0.0, 0.0)] {
            let mut ir = labeled_graph_ir(4, &[(0, 1), (1, 2), (2, 3)]);
            ir.constraints.push(IrConstraint::Pin {
                node_id: "N1".to_string(),
                x,
                y,
                span: Span::default(),
            });
            let layout = layout_with_constraints(&ir);
            assert!(
                layout.nodes.iter().all(|node| {
                    node.bounds.x.is_finite()
                        && node.bounds.y.is_finite()
                        && node.bounds.width.is_finite()
                        && node.bounds.height.is_finite()
                }),
                "pin ({x}, {y}) produced non-finite geometry"
            );
            assert!(layout.bounds.width.is_finite() && layout.bounds.height.is_finite());
        }
    }

