    #[test]
    fn constraint_solver_combines_signed_pins_order_and_integer_separation() {
        // A pure-Rust backend must retain the complete authored-constraint path, including
        // unrestricted negative coordinates and binary non-overlap choices. Exercise the same
        // model in both rank orientations rather than accepting a heuristic fallback as success.
        for direction in [GraphDirection::TB, GraphDirection::LR] {
            let mut ir = labeled_graph_ir(4, &[(0, 2), (1, 2), (2, 3)]);
            ir.direction = direction;
            ir.constraints = vec![
                IrConstraint::Pin {
                    node_id: "N0".to_string(),
                    x: -120.0,
                    y: -80.0,
                    span: Span::default(),
                },
                IrConstraint::SameRank {
                    node_ids: vec!["N0".to_string(), "N1".to_string()],
                    span: Span::default(),
                },
                IrConstraint::OrderInRank {
                    node_ids: vec!["N1".to_string(), "N0".to_string()],
                    span: Span::default(),
                },
                IrConstraint::MinLength {
                    from_id: "N0".to_string(),
                    to_id: "N2".to_string(),
                    min_len: 2,
                    span: Span::default(),
                },
                IrConstraint::NonOverlap {
                    node_ids: vec!["N0".to_string(), "N3".to_string()],
                    gap: 12.0,
                    span: Span::default(),
                },
            ];
            let initial: Vec<_> = (0..4)
                .map(|index| LayoutNodeBox {
                    node_index: index,
                    node_id: format!("N{index}"),
                    rank: index.saturating_sub(1),
                    order: usize::from(index == 1),
                    span: Span::default(),
                    bounds: LayoutRect {
                        x: -120.0,
                        y: -80.0,
                        width: 80.0,
                        height: 40.0,
                    },
                })
                .collect();
            let spacing = LayoutSpacing {
                node_spacing: 20.0,
                rank_spacing: 40.0,
                ..LayoutSpacing::default()
            };
            let mut stopped = initial.clone();
            assert!(solve_constraint_coordinates(&ir, &mut stopped, spacing, 0).is_err());
            assert_eq!(
                stopped, initial,
                "zero budget partially applied constraints"
            );

            let mut first_solution = None;
            for _ in 0..3 {
                let mut nodes = initial.clone();
                assert_eq!(
                    solve_constraint_coordinates(
                        &ir,
                        &mut nodes,
                        spacing,
                        CONSTRAINT_SOLVER_WALL_CLOCK_VALVE_MS,
                    ),
                    Ok(5),
                    "{direction:?}: solver fell back instead of enforcing constraints"
                );
                assert!((nodes[0].bounds.x + 120.0).abs() < 0.01);
                assert!((nodes[0].bounds.y + 80.0).abs() < 0.01);
                let (same_rank_delta, order_gap, length_gap, min_order, min_length) =
                    if direction == GraphDirection::LR {
                        (
                            nodes[0].bounds.x - nodes[1].bounds.x,
                            nodes[0].bounds.y - nodes[1].bounds.y,
                            nodes[2].bounds.x - nodes[0].bounds.x,
                            60.0,
                            240.0,
                        )
                    } else {
                        (
                            nodes[0].bounds.y - nodes[1].bounds.y,
                            nodes[0].bounds.x - nodes[1].bounds.x,
                            nodes[2].bounds.y - nodes[0].bounds.y,
                            100.0,
                            160.0,
                        )
                    };
                assert!(same_rank_delta.abs() < 0.01);
                assert!(order_gap >= min_order - 0.01);
                assert!(length_gap >= min_length - 0.01);
                let separation_x = (nodes[0].bounds.x - nodes[3].bounds.x).abs() - 80.0;
                let separation_y = (nodes[0].bounds.y - nodes[3].bounds.y).abs() - 40.0;
                assert!(separation_x >= 11.99 || separation_y >= 11.99);
                if let Some(expected) = &first_solution {
                    assert_eq!(
                        &nodes, expected,
                        "{direction:?}: solver was nondeterministic"
                    );
                } else {
                    first_solution = Some(nodes);
                }
            }
        }
    }

    #[test]
    fn constraint_solver_mip_separates_overlapping_rectangles() {
        let mut ir = labeled_graph_ir(2, &[]);
        ir.constraints.push(IrConstraint::NonOverlap {
            node_ids: vec!["N0".to_string(), "N1".to_string()],
            gap: 12.0,
            span: Span::default(),
        });
        let make_nodes = || {
            vec![
                LayoutNodeBox {
                    node_index: 0,
                    node_id: "N0".to_string(),
                    rank: 0,
                    order: 0,
                    span: Span::default(),
                    bounds: LayoutRect {
                        x: 0.0,
                        y: 0.0,
                        width: 80.0,
                        height: 40.0,
                    },
                },
                LayoutNodeBox {
                    node_index: 1,
                    node_id: "N1".to_string(),
                    rank: 1,
                    order: 0,
                    span: Span::default(),
                    bounds: LayoutRect {
                        x: 10.0,
                        y: 0.0,
                        width: 80.0,
                        height: 40.0,
                    },
                },
            ]
        };

        let mut without_constraint = make_nodes();
        let mut no_constraint_ir = ir.clone();
        no_constraint_ir.constraints.clear();
        assert_eq!(
            solve_constraint_coordinates(
                &no_constraint_ir,
                &mut without_constraint,
                LayoutSpacing::default(),
                CONSTRAINT_SOLVER_WALL_CLOCK_VALVE_MS,
            ),
            Ok(0),
            "control: the fixture must begin overlapping without a MIP row"
        );
        let initial_horizontal_gap = (without_constraint[1].bounds.x
            - (without_constraint[0].bounds.x + without_constraint[0].bounds.width))
            .max(
                without_constraint[0].bounds.x
                    - (without_constraint[1].bounds.x + without_constraint[1].bounds.width),
            );
        let initial_vertical_gap = (without_constraint[1].bounds.y
            - (without_constraint[0].bounds.y + without_constraint[0].bounds.height))
            .max(
                without_constraint[0].bounds.y
                    - (without_constraint[1].bounds.y + without_constraint[1].bounds.height),
            );
        assert!(
            initial_horizontal_gap < 0.0 && initial_vertical_gap < 0.0,
            "control failed: the initial rectangles are already disjoint"
        );

        let mut nodes = make_nodes();
        assert_eq!(
            solve_constraint_coordinates(
                &ir,
                &mut nodes,
                LayoutSpacing::default(),
                CONSTRAINT_SOLVER_WALL_CLOCK_VALVE_MS,
            ),
            Ok(1)
        );
        let horizontal_gap = (nodes[1].bounds.x - (nodes[0].bounds.x + nodes[0].bounds.width))
            .max(nodes[0].bounds.x - (nodes[1].bounds.x + nodes[1].bounds.width));
        let vertical_gap = (nodes[1].bounds.y - (nodes[0].bounds.y + nodes[0].bounds.height))
            .max(nodes[0].bounds.y - (nodes[1].bounds.y + nodes[1].bounds.height));
        assert!(
            horizontal_gap >= 12.0 - 0.01 || vertical_gap >= 12.0 - 0.01,
            "MIP did not separate the rectangles by the requested gap: {nodes:?}"
        );
    }

