    #[test]
    fn directed_path_specialization_is_exact_and_keeps_large_paths_on_tree_layout() {
        let chain_edges = (0..59).map(|index| (index, index + 1)).collect::<Vec<_>>();
        let mut chain = graph_ir(DiagramType::Flowchart, 60, &chain_edges);
        for index in 0..chain.nodes.len() {
            let label_index = chain.labels.len();
            chain.labels.push(IrLabel {
                text: if index % 2 == 0 {
                    format!("short {index}")
                } else {
                    format!("a deliberately wider path node label {index}")
                },
                ..IrLabel::default()
            });
            chain.nodes[index].label = Some(IrLabelId(label_index));
        }
        assert!(is_directed_path(&chain));
        assert!(estimate_layout_cost(&chain, LayoutAlgorithm::Tree).time_ms < 16);

        let dispatch = dispatch_layout_algorithm(&chain, LayoutAlgorithm::Auto);
        assert_eq!(dispatch.selected, LayoutAlgorithm::Tree);
        let guard =
            evaluate_layout_guardrails(&chain, dispatch.selected, LayoutGuardrails::default());
        assert_eq!(guard.selected_algorithm, LayoutAlgorithm::Tree);
        assert!(!guard.fallback_applied);

        for direction in [
            GraphDirection::TB,
            GraphDirection::LR,
            GraphDirection::RL,
            GraphDirection::BT,
        ] {
            chain.direction = direction;
            let layout = layout_diagram_tree(&chain);
            let specialized = build_directed_path_edge_paths(
                &chain,
                &layout.nodes,
                &BTreeSet::new(),
                EdgeRouting::default(),
            )
            .expect("directed path should take the obstacle-free router");
            let generic = build_edge_paths(
                &chain,
                &layout.nodes,
                &[],
                &BTreeSet::new(),
                EdgeRouting::default(),
            );
            assert_eq!(specialized, generic, "direction={direction:?}");
        }

        let branch = graph_ir(DiagramType::Flowchart, 5, &[(0, 1), (1, 2), (1, 3), (3, 4)]);
        let cycle = graph_ir(DiagramType::Flowchart, 3, &[(0, 1), (1, 2), (2, 0)]);
        assert!(!is_directed_path(&branch));
        assert!(!is_directed_path(&cycle));
    }

    #[test]
    fn certified_lr_path_prefix_relayout_matches_full_pipeline() {
        const LABELS: [&str; 59] = [
            "User",
            "Object Store",
            "Database 2",
            "Café latency 3",
            "Message Queue",
            "Retry & backoff 5",
            "Validate input",
            "Überprüfung",
            "Résumé job",
            "API Gateway",
            "Résumé job 10",
            "Load Balancer",
            "Message Queue",
            "Validate input",
            "API Gateway",
            "API Gateway 15",
            "Ingestion",
            "Session Store 17",
            "Read Replica",
            "Database",
            "Validate input 20",
            "Diff & merge",
            "Check permissions",
            "Check permissions 23",
            "Load Balancer 24",
            "User's session",
            "Persist record",
            "Überprüfung",
            "Cache",
            "Scheduler",
            "Database",
            "Read Replica",
            "Parse <config> 32",
            "Aggregate results",
            "Validate input",
            "naïve retry 35",
            "Message Queue 36",
            "User",
            "Read Replica",
            "Parse <config>",
            "CDN",
            "Fan out",
            "Fan out 42",
            "Emit audit event 43",
            "Cache",
            "User",
            "Aggregate results 46",
            "Session Store",
            "Scheduler",
            "Rollback on failure 545",
            "Scheduler",
            "Message Queue",
            "Read Replica",
            "Normalize payload",
            "Client",
            "Scheduler",
            "Parse <config> 552",
            "Normalize payload 553",
            "Session Store",
        ];
        let make_path = |node_count: usize| {
            let edges = (0..node_count.saturating_sub(1))
                .map(|index| (index, index + 1))
                .collect::<Vec<_>>();
            let mut ir = graph_ir(DiagramType::Flowchart, node_count, &edges);
            ir.direction = GraphDirection::LR;
            for (node_index, label) in LABELS.iter().take(node_count).enumerate() {
                let label_index = ir.labels.len();
                ir.labels.push(IrLabel {
                    text: (*label).to_owned(),
                    ..IrLabel::default()
                });
                ir.nodes[node_index].label = Some(IrLabelId(label_index));
            }
            ir
        };

        let base = make_path(55);
        let mut cached = Arc::unwrap_or_clone(layout_diagram_traced(&base).layout);
        let prefix = certify_directed_path_layout_prefix(&base, &cached, 20, 19)
            .expect("sequential LR prefix should certify");

        let next = make_path(59);
        assert!(try_relayout_directed_path_suffix(
            &next,
            &mut cached,
            &prefix
        ));
        let expected = layout_diagram_traced(&next).layout;
        assert_eq!(cached, *expected);

        // Algebraically rebuilding each suffix position from the previous rendered box changes
        // floating-point associativity. The primary invariant above (cached == *expected)
        // guarantees prefix relayout bit-for-bit matches full layout.
        let spacing = LayoutSpacing::default();
        let metrics = fm_core::FontMetrics::default_metrics();
        let mut right = expected.nodes[19].bounds.x + expected.nodes[19].bounds.width;
        let mut rounded_differently = false;
        for (node, expected_node) in next.nodes[20..].iter().zip(&expected.nodes[20..]) {
            let (width, _) = compute_node_size(&next, node, &metrics);
            let reconstructed_x = right + spacing.rank_spacing;
            rounded_differently |= reconstructed_x.to_bits() != expected_node.bounds.x.to_bits();
            right = reconstructed_x + width;
        }
        let _ = rounded_differently;

        let before_fallback = cached.clone();
        let mut branch = next;
        branch.edges[52].from = IrEndpoint::Node(IrNodeId(51));
        branch.direction = GraphDirection::LR;
        assert!(!try_relayout_directed_path_suffix(
            &branch,
            &mut cached,
            &prefix
        ));
        assert_eq!(cached, before_fallback, "failed reuse must not mutate");
    }

    #[test]
    fn directed_path_suffix_with_edge_labels_falls_back_without_mutation() {
        // The path specialization deliberately excludes graphs with fewer than three nodes.
        // Start with an eligible prefix so the assertions below reach suffix-label rejection.
        let mut base = graph_ir(DiagramType::Flowchart, 3, &[(0, 1), (1, 2)]);
        base.direction = GraphDirection::LR;
        let before = layout_diagram_tree(&base);
        let prefix = certify_directed_path_layout_prefix(&base, &before, 3, 2)
            .expect("unlabelled sequential LR path should certify");
        let text = "Confirm available inventory and reserve every requested item before continuing";
        let (text_width, _) = fm_core::FontMetrics::default_metrics().estimate_dimensions(text);
        let needed_gap = text_width.mul_add(1.4, 40.0);

        // A label on the boundary edge or a later appended edge requires the full layout.
        for edge_index in [2, 3] {
            let mut next = graph_ir(DiagramType::Flowchart, 5, &[(0, 1), (1, 2), (2, 3), (3, 4)]);
            next.direction = GraphDirection::LR;
            let label_index = next.labels.len();
            next.labels.push(IrLabel {
                text: text.to_string(),
                ..IrLabel::default()
            });
            next.edges[edge_index].label = Some(IrLabelId(label_index));
            let mut cached = before.clone();
            assert!(!try_relayout_directed_path_suffix(
                &next,
                &mut cached,
                &prefix
            ));
            assert_eq!(cached, before, "failed reuse must not mutate the cache");

            let full = layout_diagram_tree(&next);
            let source = full.nodes[edge_index].bounds;
            let target = full.nodes[edge_index + 1].bounds;
            let gap = target.x - (source.x + source.width);
            assert!(
                gap + 0.01 >= needed_gap,
                "the full fallback must reserve space for the appended label"
            );
        }
    }

