        let captured_clone = Arc::clone(&captured);

        let fmt_layer = tracing_subscriber::fmt::layer()
            .json()
            .with_writer(move || {
                let captured = Arc::clone(&captured_clone);
                CaptureWriter::new(captured)
            })
            .with_target(false)
            .with_level(true);

